    _r.tag = Z_OPTIONVAL_ZOWNERSHIP_TAG_SOME;
    _r.data.some = _this->entries[idx].value;
    _this->entries[idx].alive = 0;
    _this->indices[slot] = Z_T1880_INDEX_DELETED;
    _this->length--;
